public class BookmarkDBAdapterV3 : BookmarkDBAdapter {

	static readonly int TYPE_ID_OFFSET = 48;

	static readonly int V3_ADDRESS_COL = 0;
	static readonly int V3_CATEGORY_COL = 1;
	static readonly int V3_COMMENT_COL = 2;

	static readonly int VERSION = 3;
	static readonly Schema V3_SCHEMA = new Schema(VERSION, "ID",
		new Field[] { LongField.INSTANCE, StringField.INSTANCE, StringField.INSTANCE },
		new string[] { "Address", "Category", "Comment" });

	static int[] INDEXED_COLUMNS = new int[] { V3_ADDRESS_COL, V3_CATEGORY_COL };

	private DBHandle dbHandle;
	private Table[] tables;
	private AddressMap addressMap;

	public BookmarkDBAdapterV3(DBHandle handle, bool create, int[] typeIDs, AddressMap addrMap)
    {
		this.addressMap = addrMap;
		dbHandle = handle;
		if (typeIDs.length > 0) {
			tables = new Table[typeIDs[typeIDs.length - 1] + 1];
		}
		else {
			tables = new Table[0];
		}
		if (create) {
			for (int i = 0; i < typeIDs.length; i++) {
				int id = typeIDs[i];
				tables[id] =
					handle.createTable(BOOKMARK_TABLE_NAME + id, V3_SCHEMA, INDEXED_COLUMNS);
			}
		}
		else {
			Table bmt = handle.getTable(BOOKMARK_TABLE_NAME);
			if (bmt != null && bmt.getRecordCount() != 0) {
				// Previous version improperly upgraded and left this empty table behind empty
				throw new VersionException(true);
			}
			if (handle.getTable(BookmarkTypeDBAdapter.TABLE_NAME) == null) {
				// Indicates use of Bookmark Properties
				throw new VersionException(true);
			}
			else if (typeIDs.length != 0) {
				int version = -1;
				for (int i = 0; i < typeIDs.length; i++) {
					int id = typeIDs[i];
					string tableName = BOOKMARK_TABLE_NAME + id;
					Table table = handle.getTable(tableName);
					if (table != null) {
						int schemaVersion = table.getSchema().getVersion();
						if (version >= 0 && schemaVersion != version) {
							throw new IOException("Inconsistent bookmark table versions");
						}
						version = schemaVersion;
					}
					tables[id] = table;
				}
				if (version >= 0 && version != VERSION) {
					throw new VersionException(false);
				}
			}
		}
	}

	private Table getTable(long id) {
		int tableID = (int) (id >> TYPE_ID_OFFSET);
		if (tableID >= tables.length) {
			return null;
		}
		return tables[tableID];
	}

	/* @Override */
	DBRecord getRecord(long id)
